CREATE TABLE IF NOT EXISTS tasks (task_id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, proposal_version_id TEXT NOT NULL REFERENCES proposal_versions(proposal_version_id), authorization_grant_id TEXT NOT NULL REFERENCES authorization_grants(grant_id), state TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS work_items (work_item_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), agent_id TEXT NOT NULL, function_id TEXT NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS execution_attempts (attempt_id TEXT PRIMARY KEY, work_item_id TEXT NOT NULL REFERENCES work_items(work_item_id), request_id TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL, last_sequence INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resource_leases (lease_id TEXT PRIMARY KEY, resource_key TEXT NOT NULL, attempt_id TEXT NOT NULL REFERENCES execution_attempts(attempt_id), fencing_token INTEGER NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, released_at TEXT, UNIQUE(resource_key, fencing_token));
CREATE TABLE IF NOT EXISTS outbox (message_id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES execution_attempts(attempt_id), request_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, message_type TEXT NOT NULL, payload_json TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(idempotency_key, message_type));
CREATE TABLE IF NOT EXISTS inbox (consumer_id TEXT NOT NULL, message_id TEXT NOT NULL, payload_digest TEXT NOT NULL, applied_at TEXT NOT NULL, PRIMARY KEY(consumer_id, message_id));
